"""Add synchronized commercial draft quote snapshots and sourcing-plan links."""
from alembic import op

revision = '0013_proc_customer_quotes'
down_revision = '0012_proc_document_jobs'
branch_labels = None
depends_on = None

SQL = "-- Current commercial draft snapshots only. No quote sending or approval authority.\nCREATE TABLE public.proc_customer_quotes (\n    tenant varchar(64) NOT NULL,\n    id varchar(64) NOT NULL,\n    source_revision integer NOT NULL CHECK(source_revision>=1),\n    plan_id varchar(64) NOT NULL,\n    net numeric NOT NULL CHECK(net>0),\n    cost numeric NOT NULL CHECK(cost>=0),\n    contribution numeric NOT NULL,\n    margin_pct numeric NOT NULL,\n    status text NOT NULL CHECK(status='draft_requires_commercial_review'),\n    sent boolean NOT NULL CHECK(NOT sent),\n    note text NOT NULL,\n    source_snapshot jsonb NOT NULL CHECK(jsonb_typeof(source_snapshot)='object'),\n    PRIMARY KEY(tenant,id),\n    FOREIGN KEY(tenant,id) REFERENCES public.records(tenant,id) DEFERRABLE INITIALLY DEFERRED,\n    FOREIGN KEY(tenant,plan_id) REFERENCES public.proc_plans(tenant,id) DEFERRABLE INITIALLY DEFERRED,\n    CHECK(contribution=net-cost)\n);\nCREATE INDEX ix_proc_customer_quotes_plan ON public.proc_customer_quotes(tenant,plan_id);\nALTER TABLE public.proc_customer_quotes ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.proc_customer_quotes FORCE ROW LEVEL SECURITY;\nCREATE POLICY tenant_scope ON public.proc_customer_quotes TO supplypilot_app\n    USING(tenant=NULLIF(current_setting('supplypilot.tenant',true),''))\n    WITH CHECK(tenant=NULLIF(current_setting('supplypilot.tenant',true),''));\nCREATE POLICY migration_owner ON public.proc_customer_quotes TO supplypilot_migrator USING(true) WITH CHECK(true);\nREVOKE ALL ON TABLE public.proc_customer_quotes FROM PUBLIC,supplypilot_app;\nGRANT SELECT ON TABLE public.proc_customer_quotes TO supplypilot_app;\n\nCREATE FUNCTION public.sync_procurement_customer_quote()\nRETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp\nAS $$ DECLARE d jsonb; key text;\nBEGIN\n    IF TG_OP='UPDATE' AND (OLD.kind='customer_quote' OR NEW.kind='customer_quote') AND\n       (OLD.tenant,OLD.id,OLD.kind) IS DISTINCT FROM (NEW.tenant,NEW.id,NEW.kind) THEN\n        RAISE EXCEPTION 'Customer quote identity, tenant and kind are immutable' USING ERRCODE='23514';\n    END IF;\n    IF TG_OP='DELETE' THEN\n        IF OLD.kind='customer_quote' THEN DELETE FROM public.proc_customer_quotes WHERE tenant=OLD.tenant AND id=OLD.id; END IF;\n        RETURN OLD;\n    END IF;\n    IF NEW.kind<>'customer_quote' THEN RETURN NEW; END IF;\n    d:=NEW.data::jsonb;\n    FOREACH key IN ARRAY ARRAY['plan_id','status','note'] LOOP\n        IF jsonb_typeof(d->key) IS DISTINCT FROM 'string' THEN\n            RAISE EXCEPTION 'Customer quote metadata must be strings' USING ERRCODE='23514';\n        END IF;\n    END LOOP;\n    FOREACH key IN ARRAY ARRAY['net','cost','contribution','margin_pct'] LOOP\n        IF jsonb_typeof(d->key) IS DISTINCT FROM 'string' OR\n           (d->>key) !~ '^-?[0-9]+(\\.[0-9]{1,2})?$' THEN\n            RAISE EXCEPTION 'Customer quote amounts require finite decimal strings with at most two places' USING ERRCODE='23514';\n        END IF;\n    END LOOP;\n    IF jsonb_typeof(d->'sent') IS DISTINCT FROM 'boolean' THEN\n        RAISE EXCEPTION 'Customer quote sent flag must be boolean' USING ERRCODE='23514';\n    END IF;\n    -- Preserve the application-calculated margin. SQL rounding is not substituted\n    -- for Decimal's half-even rounding, nor is historical cost tied to a live plan.\n    INSERT INTO public.proc_customer_quotes VALUES(NEW.tenant,NEW.id,NEW.revision,d->>'plan_id',\n        (d->>'net')::numeric,(d->>'cost')::numeric,(d->>'contribution')::numeric,\n        (d->>'margin_pct')::numeric,d->>'status',(d->>'sent')::boolean,d->>'note',d)\n    ON CONFLICT(tenant,id) DO UPDATE SET source_revision=EXCLUDED.source_revision,\n        plan_id=EXCLUDED.plan_id,net=EXCLUDED.net,cost=EXCLUDED.cost,\n        contribution=EXCLUDED.contribution,margin_pct=EXCLUDED.margin_pct,\n        status=EXCLUDED.status,sent=EXCLUDED.sent,note=EXCLUDED.note,\n        source_snapshot=EXCLUDED.source_snapshot;\n    RETURN NEW;\nEND $$;\nREVOKE ALL ON FUNCTION public.sync_procurement_customer_quote() FROM PUBLIC,supplypilot_app;\nCREATE TRIGGER records_customer_quote_sync AFTER INSERT OR UPDATE OR DELETE ON public.records\nFOR EACH ROW EXECUTE FUNCTION public.sync_procurement_customer_quote();\nUPDATE public.records SET data=data WHERE kind='customer_quote';\n"

def upgrade():
    op.execute(SQL)

def downgrade():
    raise RuntimeError('Restore a reviewed backup; automatic customer-quote projection removal is disabled.')
